          "concept": "이 수업에서는 **Local Variables vs Global Variables (kansua1.py)**을 Python 관점에서 다룹니다. 변수(Variable)는 값을 담는 이름이고, 입력값은 처음에는 문자열로 들어오는 경우가 많다는 점을 함께 기억합니다.\n\nPython은 변수(Variable), 리스트(List), 딕셔너리(Dictionary), 함수(Function), 클래스(Class)를 비교적 짧은 문법으로 다룰 수 있는 언어입니다. 그래서 처음에는 문법 이름을 외우기보다, 값이 어떤 객체로 저장되고 어떤 순서로 처리되는지 직접 실행해 보는 것이 좋습니다.\n\n샌드박스에서 예제를 조금씩 바꾸어 실행하면 입력값, 중간 처리, 출력 결과가 어떻게 연결되는지 보입니다. 특히 타입 변환, 조건 분기, 반복문, 함수 호출은 작은 차이로 결과가 달라질 수 있으니 실행 전 예상과 실행 후 결과를 비교하세요.\n\n시험과 실습에서는 \"이 문법이 무엇인가\"뿐 아니라 \"왜 이 상황에서 필요한가\"를 묻는 경우가 많습니다. Local Variables vs Global Variables (kansua1.py)의 역할을 한 문장으로 설명하고, 짧은 Python 코드로 확인할 수 있으면 이 단원의 목표를 달성한 것입니다.",
